SELECT PersonId, 'ANTICHOLIN_N05' AS VarName, ABS(CHECKSUM(DrugName)) % 100000 AS DpValue, StartAt, TreatId, ai.AtcName AS Caption FROM dbo.OngoingTreatment ot LEFT JOIN dbo.KBAtcIndex ai ON ai.AtcCode = ot.ATC WHERE ( PersonId IN (/*PIDS*/) ) AND ( ot.ATC  COLLATE Latin1_General_CI_AI  LIKE 'N05A%'  COLLATE Latin1_General_CI_AI  ) AND NOT ( ( ot.ATC COLLATE Latin1_General_CI_AI LIKE 'N05AH0[34]' COLLATE Latin1_General_CI_AI ) OR ( ot.ATC COLLATE Latin1_General_CI_AI LIKE 'N05AN%' COLLATE Latin1_General_CI_AI ) )